class TestCheckStabilityProperties:
    """Property-based tests for invariants and robustness."""

    # Strategy: generate a dict with all known metric keys, values in [0, 1e6].
    metric_strategy = st.fixed_dictionaries(
        {
            "latency_ms": st.floats(min_value=0.0, max_value=1e6, allow_nan=False, allow_infinity=False),
            "error_rate": st.floats(min_value=0.0, max_value=1.0, allow_nan=False, allow_infinity=False),
            "memory_usage": st.floats(min_value=0.0, max_value=1.0, allow_nan=False, allow_infinity=False),
            "cpu_usage": st.floats(min_value=0.0, max_value=1.0, allow_nan=False, allow_infinity=False),
            "disk_io": st.floats(min_value=0.0, max_value=1e6, allow_nan=False, allow_infinity=False),
            "queue_depth": st.integers(min_value=0, max_value=100000),
        }
    )

    @given(metrics=metric_strategy)
    @settings(max_examples=100, deadline=None)
    def test_result_is_valid_enum(self, metrics: Dict[str, Any]):
        """Result must always be a valid `_RemediationLevel` member."""
        result = CoherenceThresholds.check_stability(metrics)
        assert isinstance(result, _RemediationLevel)

    @given(metrics_a=metric_strategy, metrics_b=metric_strategy)
    @settings(max_examples=50, deadline=None)
    def test_monotonicity_invariant(self, metrics_a: Dict[str, Any], metrics_b: Dict[str, Any]):
        """
        Monotonicity: if all metrics in A are <= B, then severity(A) <= severity(B).

        This is the core aggregate scoring invariant.
        """
        # Construct a combined dict where each key takes the max of A and B.
        # This guarantees combined >= A and combined >= B component-wise.
        combined = {
            key: max(metrics_a.get(key, 0.0), metrics_b.get(key, 0.0))
            for key in set(metrics_a) | set(metrics_b)
        }

        severity_a = CoherenceThresholds.check_stability(metrics_a)
        severity_b = CoherenceThresholds.check_stability(metrics_b)
        severity_combined = CoherenceThresholds.check_stability(combined)

        # Severity ordering: STABLE(0) < LOG_WARNING(1) < RESTART_SERVICE(2) < ROLLBACK(3) < FULL_RESET(4)
        order = list(_RemediationLevel)
        idx_a = order.index(severity_a)
        idx_b = order.index(severity_b)
        idx_combined = order.index(severity_combined)

        # Combined must be at least as severe as both A and B.
        assert idx_combined >= idx_a, f"Combined less severe than A: {severity_combined} < {severity_a}"
        assert idx_combined >= idx_b, f"Combined less severe than B: {severity_combined} < {severity_b}"

    @given(metrics=metric_strategy)
    @settings(max_examples=100, deadline=None)
    def test_zero_metrics_returns_stable(self, metrics: Dict[str, Any]):
        """If all metrics are zero, result must be STABLE."""
        zero_metrics = {key: 0 for key in metrics}
        result = CoherenceThresholds.check_stability(zero_metrics)
        assert result == _RemediationLevel.STABLE

    @given(metrics=metric_strategy)
    @settings(max_examples=100, deadline=None)
    def test_scaling_invariance(self, metrics: Dict[str, Any]):
        """
        Scaling all metrics by a factor < 1 should not increase severity.
        (Scaling down reduces or maintains severity.)
        """
        scaled = {key: value * 0.5 for key, value in metrics.items()}
        original_severity = CoherenceThresholds.check_stability(metrics)
        scaled_severity = CoherenceThresholds.check_stability(scaled)

        order = list(_RemediationLevel)
        assert order.index(scaled_severity) <= order.index(original_severity), (
            f"Scaling down increased severity: {scaled_severity} > {original_severity}"
        )


